'use strict';const $=id=>document.getElementById(id);let current;
function outlinedArrow(x0,y0,cx,cy,x1,y1){const edge=(t,w)=>{const x=(1-t)**2*x0+2*(1-t)*t*cx+t*t*x1,y=(1-t)**2*y0+2*(1-t)*t*cy+t*t*y1,dx=2*((1-t)*(cx-x0)+t*(x1-cx)),dy=2*((1-t)*(cy-y0)+t*(y1-cy)),n=Math.hypot(dx,dy);return`${x-dy/n*w},${y+dx/n*w}`;};const p=[];for(let i=0;i<=24;i++)p.push(edge(.75*i/24,6));p.push(edge(.75,16),`${x1},${y1}`,edge(.75,-16));for(let i=24;i>=0;i--)p.push(edge(.75*i/24,-6));return'M'+p.join(' L')+' Z';}
$('internalArrow').setAttribute('d',outlinedArrow(0,-48,55,0,0,48));$('externalArrow').setAttribute('d',outlinedArrow(0,48,55,0,0,-48));
function forceArrow(x,base,length){if(length<=0)return '';const tip=base-length,head=Math.min(16,length),neck=tip+head;return `M${x-3} ${base} V${neck} H${x-8} L${x} ${tip} L${x+8} ${neck} H${x+3} V${base} Z`; }
function update(){const f=$('force').valueAsNumber,c=$('cop').valueAsNumber;if(!Number.isFinite(f)||f<300||f>1000||!Number.isFinite(c)||c<0||c>20){$('error').textContent='床反力は300〜1000 N、COPは0〜20 cmで入力してください。';$('status').textContent='入力を確認';return;}$('error').textContent='';const m=AnklePhysics.calculate(f,c);current=m;const x=280+c*16,top=430-m.groundLength;$('forceRange').value=f;$('copRange').value=c;$('groundArrow').setAttribute('d',forceArrow(x,430,m.groundLength));for(const id of ['groundLabel','groundValue'])$(id).setAttribute('x',x);$('groundLabel').setAttribute('y',top-40);$('groundValue').setAttribute('y',top-16);$('groundValue').textContent=`${f.toFixed(0)} N`;$('muscleArrow').setAttribute('d',forceArrow(200,400,m.tensionLength));$('muscleArrow').style.visibility=m.tension===0?'hidden':'visible';$('muscleLabel').setAttribute('y',400-m.tensionLength-40);$('muscleValue').setAttribute('y',400-m.tensionLength-16);$('muscleValue').textContent=`${m.tension.toFixed(0)} N`;
for(const [id,tx]of [['internalArrow',100],['externalArrow',665]]){$(id).setAttribute('transform',`translate(${tx} 325) rotate(${id==='internalArrow'?180:0}) scale(${m.momentScale})`);$(id).style.visibility=m.external===0?'hidden':'visible';}
$('copLabel').setAttribute('x',c>17?-24:24);$('copLabel').setAttribute('text-anchor',c>17?'end':'start');$('copHandle').setAttribute('transform',`translate(${x} 430)`);$('copHandle').setAttribute('aria-valuenow',c);$('copHandle').setAttribute('aria-valuetext',`足関節直下から${c.toFixed(1)} cm`);$('leverLine').setAttribute('d',`M280 450 V463 M280 456 H${x} M${x} 450 V463`);$('leverLabel').setAttribute('x',Math.max(345,(280+x)/2));$('leverLabel').textContent=`レバーアーム ${c.toFixed(1)} cm`;
for(const id of ['internalValue','externalValue'])$(id).textContent=`${m.external.toFixed(1)} N·m`;$('externalMetric').textContent=m.external.toFixed(1);$('internalMetric').textContent=m.internal.toFixed(1);$('tensionMetric').textContent=m.tension.toFixed(0);$('status').textContent=c===0?'レバーアーム 0':'静的な釣り合い';$('lessonTitle').textContent=c===0?'COPが足関節の直下なので、モーメントは0です':'床反力のモーメントを、底屈モーメントで支えます';$('equation').textContent=`床反力によるモーメント = ${f.toFixed(0)} N × ${m.arm.toFixed(3)} m = ${m.external.toFixed(1)} N·m`;$('tensionEquation').textContent=`筋張力 = ${m.internal.toFixed(1)} N·m ÷ 0.05 m = ${m.tension.toFixed(0)} N`;$('lessonText').textContent=c===0?'床反力の作用線が足関節中心を通るため、床反力があっても、この力による回転作用は生じません。':'COPを前方へ動かすか床反力を大きくすると、必要な底屈モーメントと筋張力が増えます。';$('sceneDesc').textContent=`床反力${f}N。COPは足関節直下から${c.toFixed(1)}cm。床反力の背屈モーメントと必要な底屈モーメントは各${m.external.toFixed(1)}Nメートル、筋張力は${m.tension.toFixed(0)}N。`;document.querySelectorAll('[data-cop]').forEach(b=>{const active=+b.dataset.cop===c;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});}
for(const id of ['force','cop']){$(id).addEventListener('input',update);$(id+'Range').addEventListener('input',()=>{$(id).value=$(id+'Range').value;update();});}document.querySelectorAll('[data-cop]').forEach(b=>b.onclick=()=>{$('cop').value=b.dataset.cop;update();});$('reset').onclick=()=>{$('force').value=600;$('cop').value=10;update();};
function copPointer(e){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('scene').getScreenCTM().inverse()),c=Math.max(0,Math.min(20,(p.x-280)/16));$('cop').value=(Math.round(c*10)/10).toFixed(1);update();}
for(const id of ['copHandle','copTrack']){const el=$(id);let drag=false;el.addEventListener('pointerdown',e=>{drag=true;el.setPointerCapture(e.pointerId);copPointer(e);e.preventDefault();});el.addEventListener('pointermove',e=>{if(drag)copPointer(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>{drag=false;});}$('copHandle').addEventListener('keydown',e=>{let c=+$('cop').value;if(e.key==='ArrowRight'||e.key==='ArrowUp')c+=.1;else if(e.key==='ArrowLeft'||e.key==='ArrowDown')c-=.1;else if(e.key==='Home')c=0;else if(e.key==='End')c=20;else return;e.preventDefault();$('cop').value=Math.max(0,Math.min(20,c)).toFixed(1);update();});update();
